const form=document.querySelector('#register-form'),password=document.querySelector('#password'),confirmPassword=document.querySelector('#password-confirm'),toggle=document.querySelector('.password-toggle');
toggle.addEventListener('click',()=>{const show=password.type==='password';password.type=show?'text':'password';confirmPassword.type=show?'text':'password';toggle.textContent=show?'隐藏':'显示'});
function errorFor(input,message){input.classList.toggle('invalid',Boolean(message));const error=input.closest('label')?.querySelector('.error');if(error)error.textContent=message;return !message}
function validate(){let ok=true;form.querySelectorAll('input[required],select[required]').forEach(input=>{if(input.type==='checkbox')return;if(!input.value.trim()){errorFor(input,'请填写此项');ok=false}else errorFor(input,'')});const email=document.querySelector('#email');if(email.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){errorFor(email,'请输入有效的邮箱地址');ok=false}if(password.value&&password.value.length<8){errorFor(password,'密码至少需要 8 位字符');ok=false}if(confirmPassword.value&&confirmPassword.value!==password.value){errorFor(confirmPassword,'两次输入的密码不一致');ok=false}const terms=document.querySelector('#terms');document.querySelector('.terms-error').textContent=terms.checked?'':'请先同意会员条款与隐私政策';if(!terms.checked)ok=false;return ok}
form.querySelectorAll('input,select').forEach(input=>input.addEventListener('input',()=>{if(input.type!=='checkbox')errorFor(input,'');if(input.id==='terms')document.querySelector('.terms-error').textContent=''}));
form.addEventListener('submit',event=>{event.preventDefault();if(!validate()){form.querySelector('.invalid')?.focus();return}const value=id=>document.querySelector(id).value.trim();const member={title:value('#title'),surname:value('#surname'),givenName:value('#given-name'),birthdate:value('#birthdate'),nationality:value('#nationality'),email:value('#email'),phone:value('#phone'),countryCode:value('#country-code'),language:value('#language'),residence:value('#residence'),province:value('#province'),city:value('#city'),postalCode:value('#postal-code'),address:value('#address'),username:value('#username'),updates:document.querySelector('#updates').checked,joinedAt:new Date().toISOString()};try{localStorage.setItem('yunxiang-member',JSON.stringify(member))}catch{}document.querySelector('#welcome-name').textContent=member.surname+member.givenName;form.hidden=true;document.querySelector('.benefit-grid').hidden=true;const success=document.querySelector('#success-view');success.hidden=false;success.scrollIntoView({behavior:'smooth',block:'center'})});
